def bbox(g,c):
    pts=[(i,j) for i in range(len(g)) for j in range(len(g[0])) if g[i][j]==c]
    rs=[a for a,_ in pts]; cs=[b for _,b in pts]
    return min(rs),max(rs),min(cs),max(cs)
