def comps(g,c):
    # connected components of color c (4-connectivity)
    h=len(g);w=len(g[0]);seen=set();res=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==c and (i,j) not in seen:
                st=[(i,j)];comp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen or not(0<=a<h and 0<=b<w) or g[a][b]!=c: continue
                    seen.add((a,b));comp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)): st.append((a+da,b+db))
                res.append(comp)
    return res
