from collections import Counter
def maxsolid(g,c):
    h=len(g); w=len(g[0]); best=(0,0,0,0)
    # histogram method per row runs
    heights=[0]*w
    for i in range(h):
        for j in range(w):
            heights[j] = heights[j]+1 if g[i][j]==c else 0
    for i in range(h):
        st=[]
        for j in range(w+1):
            hh=heights[j] if j<w else -1
            while st and heights[st[-1]]>=hh:
                left=st.pop()
                right=j-1
                w_=right-left
                h_=heights[left]
                if h_*w_>best[0]: best=(h_,w_,left,i)
            st.append(j)
    return best
